// accounts/scripts/set-secrets.py: the one-page guide for an app's remaining secrets. This lane adds a Stripe section,
// shown only when the app's wrangler env turns payments on, and a generated BYO key (never asked for, never shown).
// The script's functions are imported by Python itself (`python3 -I`), so no wrangler, no network and no port is used.

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

const SCRIPT = fileURLToPath(new URL("../scripts/set-secrets.py", import.meta.url));

/** Runs `body` (Python) with the script loaded as module `m`; its stdout, parsed as JSON. */
function py(body: string): unknown {
	const code = `
import importlib.util, json, sys
spec = importlib.util.spec_from_file_location("m", ${JSON.stringify(SCRIPT)})
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
${body}
`;
	const run = spawnSync("python3", ["-I", "-c", code], { encoding: "utf8" });
	assert.equal(run.status, 0, run.stderr);
	return JSON.parse(run.stdout);
}

const secrets = (features: string) => py(`print(json.dumps([n for s in m.sites("demo", ${features}) for n, _ in s["secrets"]]))`) as string[];

test("payments off (the default): the same two sites as before; no Stripe section", () => {
	assert.deepEqual(secrets("{}"), ["GOOGLE_CLIENT_ID", "GOOGLE_CLIENT_SECRET", "R2_PARENT_ACCESS_KEY_ID", "R2_PARENT_SECRET_ACCESS_KEY"]);
	const titles = py(`print(json.dumps([s["title"] for s in m.sites("demo", {})]))`) as string[];
	assert.equal(titles.length, 2);
	assert.ok(!titles.some((t) => /stripe/i.test(t)));
});

test("payments on: a Stripe section asks for STRIPE_SECRET_KEY (test) and STRIPE_WEBHOOK_SECRET, with copy buttons for what to type there", () => {
	assert.deepEqual(secrets(`{"payments": True}`), ["GOOGLE_CLIENT_ID", "GOOGLE_CLIENT_SECRET", "R2_PARENT_ACCESS_KEY_ID", "R2_PARENT_SECRET_ACCESS_KEY", "STRIPE_SECRET_KEY", "STRIPE_WEBHOOK_SECRET"]);
	const stripe = py(`print(json.dumps([s for s in m.sites("demo", {"payments": True}) if "Stripe" in s["title"]]))`) as { title: string; url: string; steps: [string, string[]][]; secrets: [string, string][] }[];
	assert.equal(stripe.length, 1);
	const all = JSON.stringify(stripe[0].steps);
	// test mode, said plainly, and the endpoint and events to type, as copyable values
	assert.match(all, /test mode/i);
	assert.match(all, /https:\/\/folder-sync-accounts-demo\.zach-yamaoka\.workers\.dev\/fs\/api\/auth\/stripe\/webhook/);
	for (const event of ["checkout.session.completed", "customer.subscription.created", "customer.subscription.updated", "customer.subscription.deleted"]) assert.match(all, new RegExp(event.replace(/\./g, "\\.")), event);
	for (const lookup of ["folder-sync-plus", "folder-sync-pro"]) assert.match(all, new RegExp(lookup), `the product's lookup key ${lookup}`);
	assert.match(stripe[0].url, /^https:\/\/dashboard\.stripe\.com\/test\//, "the test-mode dashboard, never live");
	assert.ok(stripe[0].steps.some(([, values]) => values.length > 0), "copy buttons");
});

test("the rendered page shows the Stripe section only when payments are on, and masks every secret box", () => {
	const html = (features: string) => py(`print(json.dumps(m.form("demo", ["STRIPE_SECRET_KEY", "STRIPE_WEBHOOK_SECRET", "GOOGLE_CLIENT_ID"], "", ${features})))`) as string;
	assert.doesNotMatch(html("{}"), /STRIPE_/);
	const on = html(`{"payments": True}`);
	assert.match(on, /name=STRIPE_SECRET_KEY type=password/);
	assert.match(on, /name=STRIPE_WEBHOOK_SECRET type=password/);
});

test("features are read from the app's own wrangler env block (a missing one is the defaults)", () => {
	assert.deepEqual(py(`print(json.dumps(m.features_of("robotparts")))`), { storage: true, sync: true, payments: false, byo: false });
	assert.deepEqual(py(`print(json.dumps(m.features_of("no-such-app")))`), { storage: true, sync: true, payments: false, byo: false });
});

test("with bring-your-own on, the encryption key is generated for the app (32 random bytes, base64), not asked for", () => {
	const generated = py(`print(json.dumps({k: len(v) for k, v in m.generated({"byo": True}).items()}))`) as Record<string, number>;
	assert.deepEqual(Object.keys(generated), ["BYO_ENCRYPTION_KEY"]);
	assert.ok(generated.BYO_ENCRYPTION_KEY >= 32, "at least 32 characters");
	assert.deepEqual(py(`print(json.dumps(list(m.generated({}))))`), []);
	const twice = py(`print(json.dumps([m.make_key() != m.make_key(), len(m.make_key())]))`) as [boolean, number];
	assert.equal(twice[0], true);
	assert.ok(twice[1] >= 43);
});
